body.script:
$(document).ready(function() {
    let studentDataLoaded = false;
    let searchTimeout;

    // Check if student_id was passed from URL and mark as auto-filled
    const urlStudentId = $('#student_id').val();
    if (urlStudentId && urlStudentId.trim() !== '') {
        console.log('Student ID auto-filled from URL:', urlStudentId);
        $('#student_id').addClass('auto-filled');

        // Automatically search for this student
        setTimeout(function() {
            searchStudent(urlStudentId.trim(), 'student_id');
        }, 500);
    }

    // University change handler - show/hide ID attachment
    $('#university').on('change', function() {
        const selectedOption = $(this).find('option:selected');
        const universityName = selectedOption.text().trim();

        console.log('Selected university:', universityName);

        // Check if university is NOT "Borg El Arab Technological University"
        if (universityName && universityName !== 'Borg El Arab Technological University') {
            $('#id_attachment_section').slideDown();
            $('#id_number_attachment').attr('data-required', 'true');
        } else {
            $('#id_attachment_section').slideUp();
            $('#id_number_attachment').attr('data-required', 'false');
            $('#id_number_attachment').val(''); // Clear the file input
        }
    });

    // Student ID input handler
    $('#student_id').on('input', function() {
        const studentId = $(this).val().trim();

        // Remove auto-filled class if user is typing
        $(this).removeClass('auto-filled');

        clearTimeout(searchTimeout);
        resetForm();
        studentDataLoaded = false;

        if (studentId.length >= 2) {
            searchTimeout = setTimeout(function() {
                searchStudent(studentId, 'student_id');
            }, 500);
        }
    });

    // National ID input handler
    $('#national_id').on('input', function() {
        const nationalId = $(this).val().trim();

        clearTimeout(searchTimeout);
        resetForm();
        studentDataLoaded = false;

        if (nationalId.length >= 2) {
            searchTimeout = setTimeout(function() {
                searchStudent(nationalId, 'national_id');
            }, 500);
        }
    });

    function searchStudent(identifier, searchType) {
        $('.loading-spinner').show();
        $('#statusMessage, #statusMessageNational').hide();

        const statusDiv = searchType === 'student_id' ? $('#statusMessage') : $('#statusMessageNational');

        $.ajax({
            url: '/get_student_data',
            type: 'POST',
            data: {
                [searchType]: identifier
            },
            success: function(response) {
                $('.loading-spinner').hide();
                console.log('=== FRONTEND DEBUG ===');
                console.log('Raw response:', response);

                try {
                    let data;
                    if (typeof response === 'string') {
                        data = JSON.parse(response);
                    } else {
                        data = response;
                    }

                    console.log('Parsed data:', data);

                    if (data && data.success) {
                        populateForm(data.data);
                        showStatus('Student found! Data loaded successfully.', 'success', statusDiv);
                        studentDataLoaded = true;

                        // Trigger university change to check ID attachment requirement
                        $('#university').trigger('change');
                    } else {
                        const errorMsg = data && data.error ? data.error : 'Student not found. Enter your data';
                        showStatus(errorMsg, 'error', statusDiv);
                        studentDataLoaded = false;
                    }
                } catch (e) {
                    console.error('Error parsing response:', e);
                    showStatus('Error processing response', 'error', statusDiv);
                    studentDataLoaded = false;
                }
            },
            error: function(xhr, status, error) {
                $('.loading-spinner').hide();
                console.error('AJAX Error:', status, error);
                console.error('Response text:', xhr.responseText);
                showStatus('Error connecting to server', 'error', statusDiv);
                studentDataLoaded = false;
            }
        });
    }

    function populateForm(data) {
        console.log('=== POPULATE FORM DEBUG ===');
        console.log('Student data:', data);

        // Fill basic fields - name and email as readonly, phone as editable
        if (data.name) {
            $('#name').val(data.name).addClass('readonly-field').prop('readonly', true);
        }
        if (data.email) {
            $('#email').val(data.email).addClass('readonly-field').prop('readonly', true);
        }
        if (data.phone) {
            $('#phone').val(data.phone).removeClass('readonly-field').prop('readonly', false);
            $('#phone').attr('required', 'required');
            $('#phone').addClass('auto-filled-editable');
        }

        console.log('Basic fields filled');

        // Try to set University
        if (data.university_id) {
            const universitySelect = $('#university');
            universitySelect.val(data.university_id);

            if (universitySelect.val() === data.university_id.toString()) {
                universitySelect.addClass('readonly-field').prop('disabled', true);
            }
        }

        // Try to set Faculty
        if (data.faculty_id) {
            const facultySelect = $('#faculty');
            facultySelect.val(data.faculty_id);

            if (facultySelect.val() === data.faculty_id.toString()) {
                facultySelect.addClass('readonly-field').prop('disabled', true);
            }
        }

        // Try to set Level
        if (data.level) {
            const levelSelect = $('#levels');
            const originalLevel = data.level;

            levelSelect.val(originalLevel);

            if (levelSelect.val() !== originalLevel) {
                // Try mapping
                let mappedValue = '';
                const levelText = originalLevel.toString().toLowerCase();

                if (levelText.includes('1') || levelText.includes('اول') || levelText.includes('one') || levelText.includes('first')) {
                    mappedValue = 'one';
                } else if (levelText.includes('2') || levelText.includes('ثان') || levelText.includes('two') || levelText.includes('second')) {
                    mappedValue = 'two';
                } else if (levelText.includes('3') || levelText.includes('ثال') || levelText.includes('three') || levelText.includes('third')) {
                    mappedValue = 'three';
                } else if (levelText.includes('4') || levelText.includes('رابع') || levelText.includes('four') || levelText.includes('fourth')) {
                    mappedValue = 'fourth';
                }

                if (mappedValue) {
                    levelSelect.val(mappedValue);
                    if (levelSelect.val() === mappedValue) {
                        levelSelect.addClass('readonly-field').prop('disabled', true);
                    }
                }
            } else {
                levelSelect.addClass('readonly-field').prop('disabled', true);
            }
        }

        // Fill GPA if available
        if (data.gpa) {
            $('#gpa').val(data.gpa).addClass('readonly-field').prop('readonly', true);
        }

        console.log('=== FORM POPULATION COMPLETE ===');
    }

    function resetForm() {
        // Reset all fields except student_id and national_id
        $('#name, #email, #gpa').val('').removeClass('readonly-field').prop('readonly', false);
        $('#phone').val('').removeClass('readonly-field auto-filled-editable').prop('readonly', false);
        $('#university, #faculty, #levels').val('').removeClass('readonly-field').prop('disabled', false);

        // Hide ID attachment section
        $('#id_attachment_section').hide();
        $('#id_number_attachment').attr('data-required', 'false').val('');

        // Remove any previously added hidden inputs
        $('.disabled-field-hidden').remove();

        // Restore required attributes
        $('#name, #email, #phone, #university, #levels').attr('required', 'required');
        $('#statusMessage, #statusMessageNational').hide();
    }

    function showStatus(message, type, targetDiv) {
        const statusDiv = targetDiv || $('#statusMessage');
        statusDiv.removeClass('status-success status-error');
        statusDiv.addClass('status-' + type);
        statusDiv.html(message);
        statusDiv.show();
    }

    $('#registrationForm').on('submit', function(e) {
        // Prevent default submission first
        e.preventDefault();

        // Remove any previously added hidden inputs
        $('.disabled-field-hidden').remove();

        // Create hidden inputs for ALL disabled fields BEFORE re-enabling them
        $('select:disabled, input:disabled').each(function() {
            var $field = $(this);
            var fieldName = $field.attr('name');
            var fieldValue = $field.val();

            if (fieldName && fieldValue) {
                $('<input>').attr({
                    type: 'hidden',
                    name: fieldName,
                    value: fieldValue,
                    class: 'disabled-field-hidden'
                }).appendTo('#registrationForm');
                console.log('Added hidden input for disabled field:', fieldName, '=', fieldValue);
            }
        });

        // Now re-enable ALL disabled fields
        $('select:disabled, input:disabled').prop('disabled', false);

        // Validation
        const status = $('input[name="status"]:checked').val();

        if (status === 'student') {
            const studentId = $('#student_id').val().trim();
            if (!studentId) {
                showStatus('Please enter a student ID', 'error', $('#statusMessage'));
                $('#student_id').focus();
                return false;
            }
        } else if (status === 'graduated') {
            const nationalId = $('#national_id').val().trim();
            if (!nationalId) {
                showStatus('Please enter a national ID', 'error', $('#statusMessageNational'));
                $('#national_id').focus();
                return false;
            }
        }

        const phoneNumber = $('#phone').val().trim();
        if (!phoneNumber) {
            showStatus('Please enter a phone number', 'error', $('#statusMessage'));
            $('#phone').focus();
            return false;
        }

        const isIdAttachmentRequired = $('#id_number_attachment').attr('data-required') === 'true';
        const hasIdAttachment = $('#id_number_attachment').get(0).files.length > 0;

        if (isIdAttachmentRequired && !hasIdAttachment) {
            showStatus('Please upload your ID number attachment', 'error', $('#statusMessage'));
            $('#id_number_attachment').focus();
            $('html, body').animate({
                scrollTop: $('#id_attachment_section').offset().top - 100
            }, 500);
            return false;
        }

        // All validation passed — submit the form natively
        console.log('=== FORM SUBMITTING ===');
        console.log('University:', $('#university').val() || $('input[name="university"].disabled-field-hidden').val());
        console.log('Faculty:', $('#faculty').val() || $('input[name="faculty"].disabled-field-hidden').val());
        console.log('Level:', $('#levels').val() || $('input[name="levels"].disabled-field-hidden').val());

        this.submit();
    });
});
